3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 本文件的测试针对“班次成功结束后，结束时记录必须保留这次成功结束时的事实”：
10	// 交给调用方的班次结果与系统保存的记录相互独立，调用方为本地展示改写自己保留
11	// 的结果（实际结束时刻、事项内容、清单项、某项关闭时间等）只能影响手中的结果；
12	// 结束前关闭事项所得结果中的关闭时间也不能再串进结束时记录。系统随后的正常
13	// 保存不得把调用方的本地修改带进已结束班次的历史，后班的处理既不改写调用方
14	// 保留的结束结果，也不改写原班次的结束时事实。
15	
16	// prepareCloseResultScenario 建立一个含未关闭事项与结束前已关闭事项的班次，
17	// 在班次结束前保留已关闭事项的关闭结果，并成功结束班次、保留结束结果。
18	// 返回结束结果、已关闭事项的关闭结果与固定的关闭时刻。
19	func prepareCloseResultScenario(t *testing.T, f *fixture) (Shift, Shift, Item, Item, time.Time) {
20		t.Helper()
21		a := mustShift(t, f, "调度", "张三", tsDay(2, 8, 0), tsDay(2, 16, 0), "")
22		open, err := f.svc.AddItem(a.ID, "压力异常待观察", SeverityImportant, "不得超压", "李四")
23		if err != nil {
24			t.Fatalf("add open item: %v", err)
25		}
26		closed, err := f.svc.AddItem(a.ID, "巡检记录归档", SeverityNormal, "", "王五")
27		if err != nil {
28			t.Fatalf("add closed item: %v", err)
29		}
30		itemClosedAt := tsDay(2, 14, 0)
31		f.svc.nowAt(func() time.Time { return itemClosedAt })
32		closedResult, err := f.svc.CloseItem(closed.ID, "张三")
33		if err != nil {
34			t.Fatalf("close item before shift close: %v", err)
35		}
36		if closedResult.ClosedAt == nil || !closedResult.ClosedAt.Equal(itemClosedAt) {
37			t.Fatalf("前置：关闭结果应记录关闭时刻 %s，got %+v", itemClosedAt, closedResult.ClosedAt)
38		}
39		shiftClosedAt := tsDay(2, 16, 0)
40		f.svc.nowAt(func() time.Time { return shiftClosedAt })
41		res, err := f.svc.CloseShift(a.ID)
42		if err != nil {
43			t.Fatalf("close shift: %v", err)
44		}
45		if !res.Closed || res.ClosedAt == nil || !res.ClosedAt.Equal(shiftClosedAt) || res.CloseRecord == nil {
46			t.Fatalf("前置：结束结果应记录成功结束时刻与结束时记录：%+v", res)
47		}
48		return a, res, open, closedResult, itemClosedAt
49	}
