51	// TestCloseShiftResultIsIndependentOfStorage：调用方改写成功结束所得结果中的
52	// 实际结束时刻、事项内容/严重程度/限制条件/后续负责人、删除清单中的一项、
53	// 已关闭事项的关闭情况与关闭时间，都只能改动手上的结果：再次查询原班次仍读到
54	// 成功结束时保存的事实，先取得的班次报告也不被连带改写；随后的正常保存同样
55	// 不把这些本地修改落进存储。
56	func TestCloseShiftResultIsIndependentOfStorage(t *testing.T) {
57		f := newFixture(t)
58		a, res, open, closedResult, itemClosedAt := prepareCloseResultScenario(t, f)
59		shiftClosedAt := *res.ClosedAt
60		forge := time.Date(2031, 5, 6, 7, 8, 9, 0, time.UTC)
61	
62		// 结束后、动手改写前先取得一份班次报告与系统班次快照，作为“另一份已取得
63		// 结果”与存储原值的凭据。
64		reportBefore, err := f.svc.ShiftReport(a.ID)
65		if err != nil {
66			t.Fatalf("report before: %v", err)
67		}
68		reportSnapshot := mustJSON(t, reportBefore)
69		storedSnapshot := mustJSON(t, func() Shift {
70			sh, _ := f.svc.GetShift(a.ID)
71			return sh
72		}())
73		closeResultSnapshot := mustJSON(t, res)
74	
75		// 改写调用方保留的结束结果：实际结束时刻。
76		*res.ClosedAt = forge
77		res.Owner = "篡改负责人"
78		if len(res.CloseRecord.Items) != 2 {
79			t.Fatalf("前置：结束时记录应含2项，got %+v", res.CloseRecord.Items)
80		}
81		// 改写未关闭事项的内容、严重程度、限制条件、后续负责人。
82		s0 := &res.CloseRecord.Items[0]
83		if s0.ItemID != open.ID {
84			t.Fatalf("前置：清单应按编号排列，首项为 %s，got %s", open.ID, s0.ItemID)
85		}
86		s0.Content = "篡改后的内容"
87		s0.Severity = SeverityUrgent
88		s0.Constraints = "篡改限制"
89		s0.FollowOwner = "篡改负责人"
90		// 改写结束前已关闭事项的关闭情况、关闭人与关闭时间。
91		s1 := &res.CloseRecord.Items[1]
92		s1.Closed = false
93		s1.CloseOperator = "篡改人"
94		*s1.ClosedAt = forge
95		// 从本地清单中移除一项。
96		res.CloseRecord.Items = res.CloseRecord.Items[:1]
97	
98		// 改写结束前关闭事项所得结果中的关闭时刻：这份结果同样不能影响结束时记录。
99		closedResultMut := closedResult
100		*closedResultMut.ClosedAt = forge
101		closedResultMut.CloseOperator = "篡改人"
102		closedResultMut.Closed = false
103	
104		// 再次查询原班次：结束时事项仍完整保留原内容、严重程度、限制条件、后续负责人
105		// 与关闭情况，清单顺序和编号不变。
106		stored, err := f.svc.GetShift(a.ID)
107		if err != nil {
108			t.Fatalf("get shift after mutation: %v", err)
109		}
110		if got := mustJSON(t, stored); got != storedSnapshot {
111			t.Fatalf("改写结束结果不得影响系统保存的班次记录\nwant %s\ngot  %s", storedSnapshot, got)
112		}
113		if !stored.Closed || stored.ClosedAt == nil || !stored.ClosedAt.Equal(shiftClosedAt) {
114			t.Fatalf("实际结束时刻应保留成功结束时的值：%+v", stored.ClosedAt)
115		}
116		if stored.Owner != "张三" || len(stored.CloseRecord.Items) != 2 {
117			t.Fatalf("负责人与清单项不应被结束结果改写：%+v", stored)
118		}
119		got0 := stored.CloseRecord.Items[0]
120		if got0.ItemID != open.ID || got0.Content != "压力异常待观察" || got0.Severity != SeverityImportant ||
121			got0.Constraints != "不得超压" || got0.FollowOwner != "李四" || got0.Closed ||
122			got0.ClosedAt != nil || got0.CloseOperator != "" {
123			t.Fatalf("未关闭事项应保留结束时原样：%+v", got0)
124		}
125		got1 := stored.CloseRecord.Items[1]
126		if !got1.Closed || got1.CloseOperator != "张三" ||
127			got1.ClosedAt == nil || !got1.ClosedAt.Equal(itemClosedAt) {
128			t.Fatalf("结束前已关闭事项的关闭人与关闭时间应保留当时的值：%+v", got1)
129		}
130	
131		// 班次报告仍是结束时事实，且与改写前先取得的那份报告一致。
132		reportAfter, err := f.svc.ShiftReport(a.ID)
133		if err != nil {
134			t.Fatalf("report after mutation: %v", err)
135		}
136		if got := mustJSON(t, reportAfter); got != reportSnapshot {
137			t.Fatalf("改写结束结果不得影响班次报告\nwant %s\ngot  %s", reportSnapshot, got)
138		}
139		if !reportAfter.ItemsAtClose || reportAfter.HistoryIncomplete || len(reportAfter.CloseItems) != 2 {
140			t.Fatalf("报告应仍展示完整的结束时记录：%+v", reportAfter)
141		}
142		if cs := findCloseItem(reportAfter, closedResult.ID); cs == nil || !cs.Closed ||
143			cs.CloseOperator != "张三" || cs.ClosedAt == nil || !cs.ClosedAt.Equal(itemClosedAt) {
144			t.Fatalf("报告中已关闭事项的关闭时间不应被关闭结果改写：%+v", cs)
145		}
146	
147		// 调用方手上的结束结果确实已是改动后的样子（独立副本允许本地展示修改）。
148		if !res.ClosedAt.Equal(forge) || len(res.CloseRecord.Items) != 1 {
149			t.Fatalf("调用方保留的结果应保留本地修改：%+v", res)
150		}
151	
152		// 随后进行一次完全正常的保存（新建不重叠班次）：原班次历史不得带入调用方
153		// 对本地结果所做的修改。
154		mustShift(t, f, "调度", "赵六", tsDay(3, 8, 0), tsDay(3, 16, 0), "")
155		storedAgain, err := f.svc.GetShift(a.ID)
156		if err != nil {
157			t.Fatalf("get shift after later save: %v", err)
158		}
159		if got := mustJSON(t, storedAgain); got != closeResultSnapshot {
160			t.Fatalf("后续正常保存不得把本地修改带进原班次历史\nwant %s\ngot  %s", closeResultSnapshot, got)
161		}
162	}
163	
164	// TestCloseResultAndPreCloseResultDoNotShareTime：结束结果中的关闭时间、结束前
165	// 关闭事项操作结果中的关闭时间与系统保存的记录三者互不共享指针；改任一处的
166	// 关闭时刻，另外两处保留当时的值。
167	func TestCloseResultAndPreCloseResultDoNotShareTime(t *testing.T) {
168		f := newFixture(t)
169		a, res, _, closedResult, itemClosedAt := prepareCloseResultScenario(t, f)
170		forge := time.Date(2031, 5, 6, 7, 8, 9, 0, time.UTC)
171	
172		// 改结束结果里已关闭事项的关闭时间，关闭事项结果与存储都不变。
173		*res.CloseRecord.Items[1].ClosedAt = forge
174		if closedResult.ClosedAt == nil || !closedResult.ClosedAt.Equal(itemClosedAt) {
175			t.Fatalf("改写结束结果不应连带改掉关闭事项结果中的关闭时刻：%+v", closedResult.ClosedAt)
176		}
177		stored, err := f.svc.GetItem(closedResult.ID)
178		if err != nil {
179			t.Fatalf("get item: %v", err)
180		}
181		if stored.ClosedAt == nil || !stored.ClosedAt.Equal(itemClosedAt) {
182			t.Fatalf("改写结束结果不应改写事项保存的关闭时刻：%+v", stored.ClosedAt)
183		}
184	
185		// 反向：再取一份结束结果并改其关闭时间，先前那份结束结果与存储不变。
186		res2, err := f.svc.GetShift(a.ID)
187		if err != nil {
188			t.Fatalf("get shift: %v", err)
189		}
190		*res2.CloseRecord.Items[1].ClosedAt = forge
191		if !res.CloseRecord.Items[1].ClosedAt.Equal(forge) {
192			t.Fatalf("本结果内的修改应保留：%v", res.CloseRecord.Items[1].ClosedAt)
193		}
194		fresh, err := f.svc.ShiftReport(a.ID)
195		if err != nil {
196			t.Fatalf("report: %v", err)
197		}
198		cs := findCloseItem(fresh, closedResult.ID)
199		if cs == nil || cs.ClosedAt == nil || !cs.ClosedAt.Equal(itemClosedAt) {
200			t.Fatalf("改写另一份结果不应影响系统保存的结束时记录：%+v", cs)
201		}
202	}
203	
204	// TestLaterShiftProcessingKeepsCloseResultAndHistory：结束时未关闭的事项后来由
205	// 下一班接收、修改并关闭，原班次的结束时记录仍显示当时未关闭，最新状态对照
206	// 显示正常业务操作后的现状；调用方保留的结束结果不随后班处理变化，调用方对
207	// 本地结果的修改也不会在后续保存时进入原班次历史。
208	func TestLaterShiftProcessingKeepsCloseResultAndHistory(t *testing.T) {
209		f := newFixture(t)
210		a, closeResult, open, _, itemClosedAt := prepareCloseResultScenario(t, f)
211		b := mustShift(t, f, "调度", "李四", tsDay(2, 16, 0), tsDay(2, 23, 0), "")
212	
213		// 下一班完成交接、接收未关闭事项，随后修改并关闭它，再结束下一班。
214		h, err := f.svc.CreateHandover(a.ID, b.ID)
215		if err != nil {
216			t.Fatalf("create handover: %v", err)
217		}
218		if len(h.Entries) != 1 || h.Entries[0].ItemID != open.ID {
219			t.Fatalf("交接清单应只含未关闭事项：%+v", h.Entries)
220		}
221		if _, err := f.svc.ProcessEntry(h.ID, open.ID, ActionConfirm, "李四", "", "", ""); err != nil {
222			t.Fatalf("confirm: %v", err)
223		}
224		if _, err := f.svc.UpdateItem(open.ID, "接班后修订内容", SeverityUrgent, "新限制", "钱七"); err != nil {
225			t.Fatalf("update in next shift: %v", err)
226		}
227		laterClosedAt := tsDay(2, 20, 0)
228		f.svc.nowAt(func() time.Time { return laterClosedAt })
229		if _, err := f.svc.CloseItem(open.ID, "李四"); err != nil {
230			t.Fatalf("close in next shift: %v", err)
231		}
232		if _, err := f.svc.CloseShift(b.ID); err != nil {
233			t.Fatalf("close next shift: %v", err)
234		}
235	
236		// 调用方保留的结束结果不随后班处理变化：未关闭事项当时仍未关闭、内容照旧。
237		s0 := closeResult.CloseRecord.Items[0]
238		if s0.ItemID != open.ID || s0.Content != "压力异常待观察" || s0.Severity != SeverityImportant ||
239			s0.Constraints != "不得超压" || s0.FollowOwner != "李四" || s0.Closed ||
240			s0.ClosedAt != nil || s0.CloseOperator != "" {
241			t.Fatalf("保留的结束结果应仍是当时未关闭的事实：%+v", s0)
242		}
243		if s1 := closeResult.CloseRecord.Items[1]; !s1.Closed ||
244			s1.ClosedAt == nil || !s1.ClosedAt.Equal(itemClosedAt) {
245			t.Fatalf("保留的结束结果中已关闭事项应保持当时的关闭时间：%+v", s1)
246		}
247	
248		// 原班次报告：结束时记录显示该事项当时未关闭；最新状态对照显示后班关闭的现状。
249		rep, err := f.svc.ShiftReport(a.ID)
250		if err != nil {
251			t.Fatalf("report original shift: %v", err)
252		}
253		cs := findCloseItem(rep, open.ID)
254		if cs == nil || cs.Closed || cs.Content != "压力异常待观察" || cs.FollowOwner != "李四" {
255			t.Fatalf("原班次结束时记录应仍显示当时未关闭：%+v", cs)
256		}
257		latest := rep.LatestItems[open.ID]
258		if !latest.Closed || latest.CurrentShiftID != b.ID || latest.FollowOwner != "钱七" ||
259			latest.ClosedAt == nil || !latest.ClosedAt.Equal(laterClosedAt) {
260			t.Fatalf("最新状态对照应显示后班处理后的现状：%+v", latest)
261		}
262	
263		// 调用方改写手上的结束结果，再触发一次正常保存：原班次历史不得被带入修改。
264		forge := time.Date(2031, 5, 6, 7, 8, 9, 0, time.UTC)
265		wantSnapshot := mustJSON(t, closeResult)
266		*closeResult.ClosedAt = forge
267		closeResult.CloseRecord.Items[0].Content = "篡改内容"
268		*closeResult.CloseRecord.Items[1].ClosedAt = forge
269		mustShift(t, f, "巡检", "孙八", tsDay(3, 8, 0), tsDay(3, 16, 0), "")
270		stored, err := f.svc.GetShift(a.ID)
271		if err != nil {
272			t.Fatalf("get shift after later save: %v", err)
273		}
274		if got := mustJSON(t, stored); got != wantSnapshot {
275			t.Fatalf("后续正常保存不得把本地修改带进原班次历史\nwant %s\ngot  %s", wantSnapshot, got)
276		}
277	}
278	
279	// TestEmptyShiftCloseResultLeavesExplicitEmptyRecord：没有事项的班次结束后仍留下
280	// 明确的空记录（非 nil、空清单），与旧数据缺少结束时记录相区别；调用方向手上
281	// 的空结果塞事项或改结束时刻不影响系统保存的空记录。
282	func TestEmptyShiftCloseResultLeavesExplicitEmptyRecord(t *testing.T) {
283		f := newFixture(t)
284		e := mustShift(t, f, "调度", "张三", tsDay(2, 8, 0), tsDay(2, 16, 0), "")
285		closedAt := tsDay(2, 16, 0)
286		f.svc.nowAt(func() time.Time { return closedAt })
287		res, err := f.svc.CloseShift(e.ID)
288		if err != nil {
289			t.Fatalf("close empty shift: %v", err)
290		}
291		if !res.Closed || res.CloseRecord == nil || len(res.CloseRecord.Items) != 0 {
292			t.Fatalf("空清单结束应留下明确的空记录：%+v", res)
293		}
294		snapshot := mustJSON(t, res)
295	
296		forge := time.Date(2031, 5, 6, 7, 8, 9, 0, time.UTC)
297		*res.ClosedAt = forge
298		res.CloseRecord.Items = append(res.CloseRecord.Items, CloseItemSnapshot{ItemID: "I999", Content: "篡改事项"})
299	
300		stored, err := f.svc.GetShift(e.ID)
301		if err != nil {
302			t.Fatalf("get shift: %v", err)
303		}
304		if got := mustJSON(t, stored); got != snapshot {
305			t.Fatalf("改写空班次的结束结果不应影响系统保存的空记录\nwant %s\ngot  %s", snapshot, got)
306		}
307		if stored.CloseRecord == nil || len(stored.CloseRecord.Items) != 0 ||
308			stored.ClosedAt == nil || !stored.ClosedAt.Equal(closedAt) {
309			t.Fatalf("系统中应仍是明确的空记录与原结束时刻：%+v", stored)
310		}
311		rep, err := f.svc.ShiftReport(e.ID)
312		if err != nil {
313			t.Fatalf("report: %v", err)
314		}
315		if !rep.ItemsAtClose || rep.HistoryIncomplete || len(rep.CloseItems) != 0 {
316			t.Fatalf("空记录结束后应标为结束时记录且清单为空，不是历史不完整：%+v", rep)
317		}
318	}
319	
320	// TestCloseShiftFailureLeavesNoRecord：接班交接尚未接收齐全时结束班次属于校验
321	// 失败，必须返回零值结果与明确错误，不留下结束时记录、不写结束时刻，系统中的
322	// 班次仍保持进行中；交接补齐后重试成功，以那次成功时为准留下记录。
323	func TestCloseShiftFailureLeavesNoRecord(t *testing.T) {
324		f := newFixture(t)
325		a := mustShift(t, f, "调度", "张三", tsDay(2, 8, 0), tsDay(2, 16, 0), "")
326		it, err := f.svc.AddItem(a.ID, "遗留事项", SeverityNormal, "", "李四")
327		if err != nil {
328			t.Fatalf("add item: %v", err)
329		}
330		failAt := tsDay(2, 16, 0)
331		f.svc.nowAt(func() time.Time { return failAt })
332		if _, err := f.svc.CloseShift(a.ID); err != nil {
333			t.Fatalf("交班班次本身没有接班交接，应能结束：%v", err)
334		}
335		b := mustShift(t, f, "调度", "李四", tsDay(2, 16, 0), tsDay(2, 23, 0), "")
336		h, err := f.svc.CreateHandover(a.ID, b.ID)
337		if err != nil {
338			t.Fatalf("create handover: %v", err)
339		}
340		own, err := f.svc.AddItem(b.ID, "本班新增事项", SeverityNormal, "", "李四")
341		if err != nil {
342			t.Fatalf("add own item: %v", err)
343		}
344	
345		// 接班交接仍有待处理项：结束接班班次必须失败。
346		f.svc.nowAt(func() time.Time { return tsDay(2, 22, 0) })
347		res, err := f.svc.CloseShift(b.ID)
348		if !errors.Is(err, ErrHandoverState) {
349			t.Fatalf("接班交接未完成时结束应报 ErrHandoverState，got %v", err)
350		}
351		if res.ID != "" || res.Closed || res.ClosedAt != nil || res.CloseRecord != nil {
352			t.Fatalf("失败时应返回零值结果，不能留下结束时记录：%+v", res)
353		}
354		stored, err := f.svc.GetShift(b.ID)
355		if err != nil {
356			t.Fatalf("get shift: %v", err)
357		}
358		if stored.Closed || stored.ClosedAt != nil || stored.CloseRecord != nil {
359			t.Fatalf("校验失败后班次应仍在进行中、无结束时记录：%+v", stored)
360		}
361		rep, err := f.svc.ShiftReport(b.ID)
362		if err != nil {
363			t.Fatalf("report: %v", err)
364		}
365		if rep.ItemsAtClose || rep.HistoryIncomplete || len(rep.CloseItems) != 0 {
366			t.Fatalf("失败后报告不应出现结束时记录：%+v", rep)
367		}
368		if len(rep.Items) != 1 || rep.Items[0].ID != own.ID {
369			t.Fatalf("进行中班次应仍展示当前事项：%+v", rep.Items)
370		}
371	
372		// 补齐交接后重试成功，以成功时刻留下完整记录：本班新增事项与已接收事项都在。
373		if _, err := f.svc.ProcessEntry(h.ID, it.ID, ActionConfirm, "李四", "", "", ""); err != nil {
374			t.Fatalf("confirm: %v", err)
375		}
376		successAt := tsDay(2, 22, 30)
377		f.svc.nowAt(func() time.Time { return successAt })
378		ok, err := f.svc.CloseShift(b.ID)
379		if err != nil {
380			t.Fatalf("retry close: %v", err)
381		}
382		if !ok.Closed || ok.ClosedAt == nil || !ok.ClosedAt.Equal(successAt) ||
383			ok.CloseRecord == nil || len(ok.CloseRecord.Items) != 2 {
384			t.Fatalf("重试成功应以成功时刻留下含两项的结束时记录：%+v", ok)
385		}
386		if ok.CloseRecord.Items[0].ItemID != it.ID || ok.CloseRecord.Items[1].ItemID != own.ID {
387			t.Fatalf("结束时记录应按编号保留本班新增与已接收事项：%+v", ok.CloseRecord.Items)
388		}
389	}
